head.script:
scwin.onLoadComplete = function() {}
scwin.btn_select_onclick = function() {
    scwin.fn_search();
};
scwin.fn_search = function() {
    if (tab_sftyDstcKndAplyStdInfo.getSelectedTabIndex() == "0") {
        dm_searchInfo.set("pageIndex", 1);
        dl_sftyDstcDvs.removeAll();
        //04-조회, 05-저장, 09-기타
        //( 공통에서 로그 기록 : 06-다운로드, 07-보고서인쇄, 08-보고서저장 )
        ajaxLib.executeSubmission("sbm_selectSftyDstcKndAplyStdInfo", {
            logDvsCd: "04",
            disableID: "btn_select"
        });
    } else if (tab_sftyDstcKndAplyStdInfo.getSelectedTabIndex() == "1") {
        dl_sftyDstcDvsPivot.removeAll();
        dm_searchInfo.set("PES_MGZN_INSTLDVCD", "all");
        dm_searchInfo.set("ES_MGZN_INSTLDVCD", "all");
        //dm_searchInfo.set( "AMN_SFTY_DSTC_KND_CD" , "1" );		//항공기지거리로 픽스
        //04-조회, 05-저장, 09-기타
        //( 공통에서 로그 기록 : 06-다운로드, 07-보고서인쇄, 08-보고서저장 )
        ajaxLib.executeSubmission("sbm_selectSftyDstcKndAplyStdInfoPivot", {
            logDvsCd: "04",
            disableID: "btn_select"
        });
    }
};
scwin.sbm_selectSftyDstcKndAplyStdInfo_successCallback = function(resJson) {
    dl_sftyDstcDvs.reform();
    dm_searchInfo.set("pageCnt", resJson.pageCnt);
    spn_totCntGrp.setLabel(resJson.totalCnt); // 총건수
    spn_cntGrp.setLabel(dl_sftyDstcDvs.getRowCount()); // 조회건수
};
scwin.sbm_selectSftyDstcKndAplyStdInfoPivot_successCallback = function(resJson) {
    dl_sftyDstcDvsPivot.reform();
    WebSquare.wUnit.getJq('.pvtTotal').addClass("w2PivotTableDisplayNone");
    WebSquare.wUnit.getJq('.pvtTotalLabel').addClass("w2PivotTableDisplayNone");
    WebSquare.wUnit.getJq('.pvtGrandTotal').addClass("w2PivotTableDisplayNone");
};
scwin.grd_qtdstStdInfo_onscrollend = function() {
    var pageIndex = parseInt(dm_searchInfo.get("pageIndex"));
    pageIndex++;
    if (pageIndex <= parseInt(dm_searchInfo.get("pageCnt"))) {
        dm_searchInfo.set("pageIndex", pageIndex); // 페이지번호
        //04-조회, 05-저장, 09-기타
        //( 공통에서 로그 기록 : 06-다운로드, 07-보고서인쇄, 08-보고서저장 )
        ajaxLib.executeSubmission("sbm_selectSftyDstcKndAplyStdInfo", {
            disableID: "grd_qtdstStdInfo"
        });
    }
};
scwin.btn_save_onclick = function() {
    if (valLib.validateGroup(grd_qtdstStdInfo)) {
        var valRole = [{
            id: "PES_DNGR_WTSPL_GRP_CD",
            mandatory: true,
            maxlength: 1
        }, {
            id: "AMN_SFTY_DSTC_KND_CD",
            mandatory: true,
            maxlength: 3
        }, {
            id: "PES_MGZN_INSTLDVCD",
            mandatory: true,
            maxlength: 8
        }, {
            id: "ES_MGZN_INSTLDVCD",
            mandatory: true,
            maxlength: 8
        }];
        if (comLib.checkSave([grd_qtdstStdInfo], [valRole])) {
            if (comLib.checkKey(dl_sftyDstcDvs, {
                    checkKeySqlId: "i.mgznsftydstcmgtcomp.mgznsftydstcmgt.checkKeySftyDstcKndAplyStdInfo",
                    checkKeyNmArr: ["AMN_SFTY_DSTC_KND_CD", "PES_MGZN_INSTLDVCD", "ES_MGZN_INSTLDVCD"]
                })) {
                //04-조회, 05-저장, 09-기타
                //( 공통에서 로그 기록 : 06-다운로드, 07-보고서인쇄, 08-보고서저장 )
                ajaxLib.executeSubmission("sbm_saveSftyDstcKndAplyStdInfo", {
                    logDvsCd: "05",
                    disableID: "btn_save"
                });
            }
        }
    }
};
scwin.sbm_saveSftyDstcKndAplyStdInfo_successCallback = function(resJson) {
    comLib.alert(comLib.formattingMessage(ComMessage.INF_0005));
    // 재조회
    if (tab_sftyDstcKndAplyStdInfo.getSelectedTabIndex() == "0") {
        dm_searchInfo.set("pageIndex", 1);
        dl_sftyDstcDvs.removeAll();
        //04-조회, 05-저장, 09-기타
        //( 공통에서 로그 기록 : 06-다운로드, 07-보고서인쇄, 08-보고서저장 )
        ajaxLib.executeSubmission("sbm_selectSftyDstcKndAplyStdInfo", {
            disableID: "btn_select"
        });
    } else if (tab_sftyDstcKndAplyStdInfo.getSelectedTabIndex() == "1") {
        dl_sftyDstcDvsPivot.removeAll();
        dm_searchInfo.set("PES_MGZN_INSTLDVCD", "all");
        dm_searchInfo.set("ES_MGZN_INSTLDVCD", "all");
        //dm_searchInfo.set( "AMN_SFTY_DSTC_KND_CD" , "1" );		//항공기지거리로 픽스
        //04-조회, 05-저장, 09-기타
        //( 공통에서 로그 기록 : 06-다운로드, 07-보고서인쇄, 08-보고서저장 )
        ajaxLib.executeSubmission("sbm_selectSftyDstcKndAplyStdInfoPivot", {
            disableID: "btn_select"
        });
    }
};
scwin.btn_insertMain_onclick = function() {
    grd_qtdstStdInfo.setFocusedCell(dl_sftyDstcDvs.insertRow(), 1);
};
scwin.btn_deleteMain_onclick = function() {
    if (dl_sftyDstcDvs.getRowStatus(grd_qtdstStdInfo.getFocusedRowIndex()) == "C") {
        dl_sftyDstcDvs.removeRow(grd_qtdstStdInfo.getFocusedRowIndex());
    } else {
        dl_sftyDstcDvs.deleteRow(grd_qtdstStdInfo.getFocusedRowIndex());
    }
};
scwin.btn_cancel_onclick = function() {
    comLib.cancelGridView(grd_qtdstStdInfo);
};
scwin.btn_excelDownload_onclick = function() {
    //type   			 : [defalut: "1"] 0 : 실제 데이터, 1 :  눈에 보이는 데이터, 2 : 들어가 있는 data 그대로(filter무시 expression 타입의 셀은 나오지 않음)
    var options = {
        "type": "1"
    };
    comLib.excelDownload("grd_qtdstStdInfo", "안전거리기준적용현황", options);
};
scwin.btn_pivotDownload_onclick = function() {
    var options = {
        type: "1"
    }; // 기본값 “1” (생략가능)
    comLib.pivotExcelDownload(grd_sftyDstcDvsPivot, "항공기지거리적용기준표", options);
};
scwin.grd_qtdstStdInfo_onrowindexchange = function(row, oldRow) {
    if (dl_sftyDstcDvs.getRowStatus(row) == 'C') {
        sbx_pesInstltnDvs.setDisabled(false);
        sbx_esInstltnDvs.setDisabled(false);
        sbx_sftyDstcKnd.setDisabled(false);
        sbx_pesDngrRating.setDisabled(false);
        ibx_dngrCfcn.setDisabled(false);
    } else {
        sbx_pesInstltnDvs.setDisabled(true);
        sbx_esInstltnDvs.setDisabled(true);
        sbx_sftyDstcKnd.setDisabled(true);
        sbx_pesDngrRating.setDisabled(true);
        ibx_dngrCfcn.setDisabled(false);
    }
};
scwin.ibx_dngrCfcn_onkeyup = function(e) {
    var val = this.getValue();
    var mc = /([0-9]{1,4})([.][0-9]{0,4})?/;
    var pt = /^([0-9]{1,4}([.][0-9]{0,4})?)$/;
    if (pt.test(val)) {} else {
        comLib.alert("자릿수는 4,4 입니다.", "ibx_dngrCfcn");
        this.setValue(val.match(mc)[0]);
    }
};
scwin.btn_printSftyDstcKndAplyStd_onclick = function() {
    var param = {
        type: "json",
        ozr: "f09/f0907/f090701/sftyDstcKndAplyStdR.ozr",
        args: ["jsonData={'list':" + JSON.stringify(dl_sftyDstcDvs.getAllJSON()) + "}"] // OZFormParam.파라미터명
    };
    popupLib.openOzViewer(param);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '항공기지거리적용기준표'탭을 클릭하여 header부분의 영역이 보여지는지를 확인한다.
    //1. After executing the sample, click the 'Air Base Distance Application Criteria' tab and check whether the header area is shown.
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tab_sftyDstcKndAplyStdInfo_tab_tabs4').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tab_sftyDstcKndAplyStdInfo').setActiveTab(1)");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. header부분의 영역이 정상적으로 보여진다. (PES탄약고시설구분코드, ES탄약고시설구분코드) (이전에는 header부분의 영역이 보여지지 않음)
    //1. The header area is displayed normally.(PES ammunition facility identification code, ES ammunition facility identification code)(Previously the header area is not shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_sftyDstcDvsPivot_col0').css('width') != '0px'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_sftyDstcDvsPivot_col1').css('width') != '0px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
